SELECT  FROM TB_HR_DEV d 

  AND d.emp_type_cd=#{filter.employeeTypeCode}
  AND (d.job_cd=#{filter.jobCode} OR d.sub_job_cd=#{filter.jobCode})
  AND d.drct_cls_cd=#{filter.directClassCode}
  AND (strpos(lower(d.dev_nm),lower(#{filter.q})) > 0 OR strpos(lower(d.mng_no),lower(#{filter.q})) > 0)

ORDER BY d.dev_nm,d.dev_id

SELECT COALESCE((SELECT h.new_ctrt_mm FROM TB_PJ_ASGN_HIST h WHERE h.asgn_id=a.asgn_id AND h.aply_dt <= #{date}
  AND h.asgn_chg_type_cd='RATE' AND h.new_ctrt_mm IS NOT NULL ORDER BY h.aply_dt DESC,h.hist_sn DESC LIMIT 1),
  (SELECT h.bfr_val::numeric FROM TB_PJ_ASGN_HIST h WHERE h.asgn_id=a.asgn_id AND h.aply_dt > #{date}
    AND h.asgn_chg_type_cd='RATE' AND h.new_ctrt_mm IS NOT NULL ORDER BY h.aply_dt,h.hist_sn LIMIT 1),a.ctrt_mm)
FROM TB_PJ_ASGN a WHERE a.asgn_id=#{id}

mapper.update:
UPDATE TB_HR_DEV_STAT SET end_dt=#{endDate,jdbcType=DATE},close_leave_sn=#{closedLeaveSequence,jdbcType=NUMERIC},
  orgnl_leave_end_dt=#{originalEndDate,jdbcType=DATE},mod_user_id='admin',mod_dttm=clock_timestamp()
WHERE dev_id=#{developerId} AND stat_sn=#{sequence}

UPDATE TB_HR_DEV SET retire_dt=#{retirement,jdbcType=DATE},work_stat_cd=#{code},
  use_yn=CASE WHEN #{retirement,jdbcType=DATE} < #{today} THEN 'N' WHEN #{resume} THEN 'Y' ELSE use_yn END,
  mod_user_id='admin',mod_dttm=clock_timestamp() WHERE dev_id=#{id}
  AND (retire_dt IS DISTINCT FROM #{retirement,jdbcType=DATE} OR work_stat_cd IS DISTINCT FROM #{code}
    OR (#{retirement,jdbcType=DATE} < #{today} AND use_yn!='N') OR (#{resume} AND use_yn!='Y'))
